export const REPORT_FIELDS=[['location','Location'],['inspectionDate','Inspection date'],['recommendedAction','Recommended action'],['departmentResponse','Department response'],['category','Category'],['priority','Priority'],['remarks','Remarks']];
export const REPORT_PRESETS={inspection:['location','recommendedAction'],followup:['location','departmentResponse']};
export function resolveReportFields(data){if(Array.isArray(data.reportFieldSelection))return REPORT_FIELDS.map(([key])=>key).filter(key=>data.reportFieldSelection.includes(key));return ['location','inspectionDate',...(data.includeRecommendedAction!==false?['recommendedAction']:[]),...(data.departmentResponse?['departmentResponse']:[]),'category','priority','remarks'];}
export function migrateReportFields(snapshot){if(Array.isArray(snapshot.fields?.reportFieldSelection))return resolveReportFields({reportFieldSelection:snapshot.fields.reportFieldSelection});const f=snapshot.fields||{},rows=snapshot.rows||[],dates=new Set(rows.filter(r=>r.include).map(r=>(snapshot.groupEdits?.[r.inspection.id]||r.inspection).date||''));return ['location',...(dates.size>1?['inspectionDate']:[]),...(f.includeRecommendedAction!==false?['recommendedAction']:[]),...(f.departmentResponse?['departmentResponse']:[]),...['category','priority','remarks'].filter(key=>rows.some(r=>r.include&&r.edit[key]?.trim()))];}
export function reportPreset(selection){const sorted=[...selection].sort().join('|');return Object.keys(REPORT_PRESETS).find(key=>[...REPORT_PRESETS[key]].sort().join('|')===sorted)||'custom';}
